import java.util.*;
public class Question_08{static boolean cycle(String v,Map<String,List<String>>g,Set<String>a,Set<String>b){if(a.contains(v))return true;if(b.contains(v))return false;a.add(v);for(String w:g.get(v))if(cycle(w,g,a,b))return true;a.remove(v);b.add(v);return false;}public static void main(String[]x){Map<String,List<String>>g=new LinkedHashMap<>();g.put("registration",List.of("assessment"));g.put("assessment",List.of("surveyor","settlement"));g.put("surveyor",List.of("settlement"));g.put("settlement",List.of());String s="registration",t="settlement";Queue<String>q=new ArrayDeque<>();Map<String,String>p=new HashMap<>();q.add(s);p.put(s,null);while(!q.isEmpty()){String v=q.remove();if(v.equals(t))break;for(String w:g.get(v))if(!p.containsKey(w)){p.put(w,v);q.add(w);}}List<String>path=new ArrayList<>();if(p.containsKey(t)){for(String v=t;v!=null;v=p.get(v))path.add(v);Collections.reverse(path);}System.out.println("Shortest path: "+path);System.out.println("Cycle detected: "+cycle(s,g,new HashSet<>(),new HashSet<>()));}}